mapper.select:
where s.enterprise_id = #{enterpriseId}
and (p.product_name like concat('%', #{keyword}, '%') or p.product_code like concat('%', #{keyword}, '%'))
and p.category_id = #{categoryId}
and (s.qty <= 0 or (rp.safety_stock is not null and s.qty - s.locked_qty <= rp.safety_stock))
order by p.product_id

mapper.update:
update t_stock set in_transit_qty = in_transit_qty - #{qty}, update_time = sysdate()
where enterprise_id = #{enterpriseId} and product_id = #{productId}
  and in_transit_qty >= #{qty}

update t_stock set qty = qty - #{qty}, update_time = sysdate()
where enterprise_id = #{enterpriseId} and product_id = #{productId}
  and qty - locked_qty >= #{qty}
